function validate(input) {
  const [obj, mutators] = input;
  if (obj === null || typeof obj !== 'object') return 'obj must be a JSON object or array.';
  const size = JSON.stringify(obj).length;
  if (size > 400000) return 'obj is too large: keep its JSON text within 4 * 10^5 characters.';
  const isNode = (value) => value !== null && typeof value === 'object';
  const stack = [obj];
  while (stack.length > 0) {
    const node = stack.pop();
    if (!Array.isArray(node) && Object.hasOwn(node, '__proto__')) return 'obj cannot use the key "__proto__".';
    for (const value of Object.values(node)) if (isNode(value)) stack.push(value);
  }
  if (!Array.isArray(mutators) || mutators.length < 1 || mutators.length >= 100000) return 'Give 1 to 99999 mutators.';
  const RESERVED = new Set(['let', 'true', 'false', 'null', '__proto__']);
  const parse = (text) => {
    const tokens = [], pattern = /\s*("(?:[^"\\]|\\.)*"|\d+|[A-Za-z_$][\w$]*|\+=|-=|[-+=.[\]])/y;
    for (let at = 0; text.slice(at).trim() !== ''; at = pattern.lastIndex) {
      pattern.lastIndex = at;
      const match = pattern.exec(text);
      if (match === null) throw new Error('cannot be read.');
      tokens.push(match[1]);
    }
    let at = 0;
    const fail = () => { throw new Error('is not a statement of the allowed form.'); };
    const take = (expected) => (tokens[at] === undefined || (expected !== undefined && tokens[at] !== expected) ? fail() : tokens[at++]);
    const name = () => { const token = take(); return /^[A-Za-z_$]/.test(token) && !RESERVED.has(token) ? token : fail(); };
    const ref = () => {
      const result = { name: name(), keys: [] };
      while (tokens[at] === '.' || tokens[at] === '[') {
        if (take() === '.') result.keys.push(name());
        else { const index = take(); if (!/^\d+$/.test(index)) fail(); result.keys.push(Number(index)); take(']'); }
      }
      return result;
    };
    const literal = (token) => { try { return JSON.parse(token); } catch { return fail(); } };
    const term = () => {
      const token = tokens[at] ?? '';
      if (token === '-' && /^\d+$/.test(tokens[at + 1] ?? '')) { at += 2; return { value: -Number(tokens[at - 1]) }; }
      if (/^\d+$/.test(token)) { at++; return { value: Number(token) }; }
      if (token.startsWith('"') || token === 'true' || token === 'false' || token === 'null') { at++; return { value: literal(token) }; }
      return { ref: ref() };
    };
    const expression = () => {
      const result = { parts: [term()], ops: [] };
      while (tokens[at] === '+' || tokens[at] === '-') { result.ops.push(take()); result.parts.push(term()); }
      return result;
    };
    let statement;
    if (tokens[0] === 'let') { take(); statement = { name: name() }; take('='); statement.expr = expression(); }
    else { statement = { target: ref() }; statement.op = take(); if (!['=', '+=', '-='].includes(statement.op) || statement.target.keys.length === 0) fail(); statement.expr = expression(); }
    if (at !== tokens.length) fail();
    return statement;
  };
  const safe = (value) => { if (typeof value === 'number' && Math.abs(value) > Number.MAX_SAFE_INTEGER) throw new Error('makes a number beyond ±2^53.'); return value; };
  for (let m = 0; m < mutators.length; m++) {
    const statements = mutators[m];
    if (!Array.isArray(statements) || statements.length > 20 || !statements.every((s) => typeof s === 'string' && s.length <= 200)) return `Mutator ${m} must be a list of at most 20 statements of at most 200 characters.`;
    // Follow the statements on the original obj, keeping this mutator's assignments aside: containers are never replaced.
    const scope = new Map([['proxy', obj]]), written = new Map(), lengths = new Map();
    const check = (node, key) => {
      if (!isNode(node)) throw new Error('reads a key of something that is not an object or array.');
      if (Array.isArray(node) !== (typeof key === 'number')) throw new Error(Array.isArray(node) ? 'uses .key on an array; use [index].' : 'uses [index] on an object; use .key.');
    };
    const get = (node, key) => {
      check(node, key);
      const own = written.get(node);
      if (own !== undefined && own.has(key)) return own.get(key);
      if (Array.isArray(node) ? key >= node.length : !Object.hasOwn(node, key)) throw new Error(`reads ${key}, which does not exist.`);
      return node[key];
    };
    const set = (node, key, value) => {
      check(node, key);
      if (isNode(value)) throw new Error('assigns an object or array; only numbers, strings, booleans and null may be assigned.');
      const own = written.get(node) ?? new Map();
      if (!own.has(key) && Object.hasOwn(node, key) && isNode(node[key])) throw new Error(`assigns to ${key}, which holds an object or array.`);
      if (Array.isArray(node)) {
        const length = lengths.get(node) ?? node.length;
        if (key > length) throw new Error(`assigns index ${key} of an array of length ${length}.`);
        if (key === length) lengths.set(node, length + 1);
      }
      own.set(key, value);
      written.set(node, own);
    };
    const read = (ref) => {
      if (!scope.has(ref.name)) throw new Error(`uses ${ref.name}, which is not defined.`);
      return ref.keys.reduce((value, key) => get(value, key), scope.get(ref.name));
    };
    const evaluate = (expr) => {
      const values = expr.parts.map((part) => safe('value' in part ? part.value : read(part.ref)));
      if (values.length === 1) return values[0];
      if (!values.every((value) => typeof value === 'number')) throw new Error('uses + or - on something that is not a number.');
      return safe(values.reduce((total, value, i) => (expr.ops[i - 1] === '+' ? total + value : total - value)));
    };
    for (const text of statements) {
      try {
        const statement = parse(text);
        if (statement.name !== undefined) {
          if (scope.has(statement.name)) throw new Error(`declares ${statement.name} a second time.`);
          scope.set(statement.name, evaluate(statement.expr));
        } else {
          const { target, op } = statement;
          const holder = read({ name: target.name, keys: target.keys.slice(0, -1) });
          const key = target.keys[target.keys.length - 1];
          let value = evaluate(statement.expr);
          if (op !== '=') {
            const current = get(holder, key);
            if (typeof current !== 'number' || typeof value !== 'number') throw new Error(`uses ${op} on something that is not a number.`);
            value = safe(op === '+=' ? current + value : current - value);
          }
          set(holder, key, value);
        }
      } catch (error) {
        return `Mutator ${m}, "${text}": ${error.message}`;
      }
    }
  }
  return null;
}

