function adapt(input, solve, kit) {
  const [obj, mutators] = input;
  const RESERVED = new Set(['let', 'true', 'false', 'null', '__proto__']);
  // Statements are read with the same small grammar the validator checks.
  const parse = (text) => {
    const tokens = [], pattern = /\s*("(?:[^"\\]|\\.)*"|\d+|[A-Za-z_$][\w$]*|\+=|-=|[-+=.[\]])/y;
    for (let at = 0; text.slice(at).trim() !== ''; at = pattern.lastIndex) {
      pattern.lastIndex = at;
      const match = pattern.exec(text);
      if (match === null) throw new Error(`Cannot read the statement "${text}".`);
      tokens.push(match[1]);
    }
    let at = 0;
    const fail = () => { throw new Error(`Cannot read the statement "${text}".`); };
    const take = (expected) => (tokens[at] === undefined || (expected !== undefined && tokens[at] !== expected) ? fail() : tokens[at++]);
    const name = () => { const token = take(); return /^[A-Za-z_$]/.test(token) && !RESERVED.has(token) ? token : fail(); };
    const ref = () => {
      const result = { name: name(), keys: [] };
      while (tokens[at] === '.' || tokens[at] === '[') {
        if (take() === '.') result.keys.push(name());
        else { const index = take(); if (!/^\d+$/.test(index)) fail(); result.keys.push(Number(index)); take(']'); }
      }
      return result;
    };
    const term = () => {
      const token = tokens[at] ?? '';
      if (token === '-' && /^\d+$/.test(tokens[at + 1] ?? '')) { at += 2; return { value: -Number(tokens[at - 1]) }; }
      if (/^\d+$/.test(token)) { at++; return { value: Number(token) }; }
      if (token.startsWith('"') || token === 'true' || token === 'false' || token === 'null') { at++; return { value: JSON.parse(token) }; }
      return { ref: ref() };
    };
    const expression = () => {
      const result = { parts: [term()], ops: [] };
      while (tokens[at] === '+' || tokens[at] === '-') { result.ops.push(take()); result.parts.push(term()); }
      return result;
    };
    let statement;
    if (tokens[0] === 'let') { take(); statement = { name: name() }; take('='); statement.expr = expression(); }
    else { statement = { target: ref() }; statement.op = take(); if (!['=', '+=', '-='].includes(statement.op) || statement.target.keys.length === 0) fail(); statement.expr = expression(); }
    if (at !== tokens.length) fail();
    return statement;
  };
  // Each mutator becomes a real function that runs its statements on whatever produce passes it.
  const build = (statements) => {
    const parsed = statements.map(parse);
    return (proxy) => {
      const scope = new Map([['proxy', proxy]]);
      const read = (ref) => ref.keys.reduce((value, key) => value[key], scope.get(ref.name));
      const evaluate = (expr) => expr.parts.map((part) => ('value' in part ? part.value : read(part.ref))).reduce((total, value, i) => (expr.ops[i - 1] === '+' ? total + value : total - value));
      parsed.forEach((statement, i) => {
        kit.trace(`${statements[i]} runs`);
        if (statement.name !== undefined) {
          scope.set(statement.name, evaluate(statement.expr));
          return;
        }
        const holder = read({ name: statement.target.name, keys: statement.target.keys.slice(0, -1) });
        const key = statement.target.keys[statement.target.keys.length - 1];
        if (statement.op === '=') holder[key] = evaluate(statement.expr);
        else if (statement.op === '+=') holder[key] += evaluate(statement.expr);
        else holder[key] -= evaluate(statement.expr);
      });
    };
  };
  // Results are compared whatever order their object keys come in.
  const canonical = (value) => {
    if (value === null || typeof value !== 'object') return value;
    if (Array.isArray(value)) return value.map(canonical);
    const sorted = {};
    for (const key of Object.keys(value).sort()) sorted[key] = canonical(value[key]);
    return sorted;
  };
  const short = (value) => { const text = JSON.stringify(value); return text.length > 80 ? `${text.slice(0, 80)}…` : text; };
  const before = JSON.stringify(obj);
  const helper = new solve(obj);
  if (!helper || typeof helper.produce !== 'function') throw new Error('ImmutableHelper needs a produce method.');
  kit.trace('new ImmutableHelper(obj) is created');
  return mutators.map((statements, index) => {
    kit.trace(`produce(mutator ${index}) is called`);
    const result = helper.produce(build(statements));
    if (result === null || typeof result !== 'object') throw new Error('produce must return an object or array.');
    if (JSON.stringify(obj) !== before) throw new Error('produce changed the original obj; it must stay exactly as it was.');
    const answer = canonical(result);
    kit.trace(`produce returns ${short(answer)}`);
    return answer;
  });
}

