class ImmutableHelper {
  constructor(obj) {
    this.obj = obj;
  }

  produce(mutator) {
    const root = this.createDraft(this.obj);
    mutator(root.proxy);
    return this.finalize(root);
  }

  createDraft(base) {
    const draft = { base, copy: null, children: new Map(), proxy: null };
    draft.proxy = new Proxy(base, {
      get: (_, key) => {
        const value = (draft.copy ?? base)[key];
        if (value === null || typeof value !== 'object') return value;
        if (!draft.children.has(key)) draft.children.set(key, this.createDraft(value));
        return draft.children.get(key).proxy;
      },
      set: (_, key, value) => {
        if (draft.copy === null) draft.copy = Array.isArray(base) ? [...base] : { ...base };
        draft.copy[key] = value;
        return true;
      },
    });
    return draft;
  }

  finalize(draft) {
    let result = draft.copy;
    for (const [key, child] of draft.children) {
      const value = this.finalize(child);
      if (value === child.base) continue;
      if (result === null) result = Array.isArray(draft.base) ? [...draft.base] : { ...draft.base };
      result[key] = value;
    }
    return result ?? draft.base;
  }
}

brute:
class ImmutableHelper {
  // Keep obj as JSON text and give every mutator a full, independent deep copy to edit directly.
  constructor(obj) {
    this.text = JSON.stringify(obj);
  }

  produce(mutator) {
    const copy = JSON.parse(this.text);
    mutator(copy);
    return copy;
  }
}

