function generate(rand, size) {
  const small = size === 'small';
  const int = (n) => Math.floor(rand() * n);
  const pick = (list) => list[int(list.length)];
  const isNode = (value) => value !== null && typeof value === 'object';
  const NAMES = ['a', 'b', 'c', 'x', 'y', 'val', 'arr', 'obj', 'count', 'list', 'data', 'items', 'info', 'flag', 'label', 'total'];
  const primitive = () => {
    const roll = rand();
    if (roll < 0.7) return int(41) - 20;
    if (roll < 0.8) return pick(['a', 'hi', '', 'x y']);
    return roll < 0.9 ? rand() < 0.5 : null;
  };
  let budget = small ? 2 + int(9) : rand() < 0.5 ? 250 : 1000;
  // A large obj keeps adding entries at the top until its budget of values is used up.
  const build = (depth, asArray) => {
    const node = asArray ? [] : {}, offset = int(NAMES.length);
    const length = !small && depth === 0 ? Infinity : 1 + int(small ? 4 : 12);
    for (let i = 0; i < length && budget > 0; i++) {
      budget--;
      const child = depth < (small ? 2 : 5) && rand() < 0.3 ? build(depth + 1, rand() < 0.4) : primitive();
      if (asArray) node.push(child);
      else node[i < NAMES.length ? NAMES[(offset + i) % NAMES.length] : `k${i}`] = child;
    }
    return node;
  };
  const obj = build(0, rand() < 0.15);
  // Each mutator is written while it is applied to its own deep copy, so every read and assignment it makes is valid.
  const makeMutator = (count) => {
    const draft = JSON.parse(JSON.stringify(obj)), statements = [];
    const refs = [{ name: 'proxy', node: draft }], numbers = [];
    let fresh = 0;
    const step = (node, key) => (Array.isArray(node) ? `[${key}]` : `.${key}`);
    const somewhere = () => {
      const start = pick(refs);
      let node = start.node, text = start.name;
      while (rand() < 0.6) {
        const keys = Object.keys(node).map((k) => (Array.isArray(node) ? Number(k) : k)).filter((k) => isNode(node[k]));
        if (keys.length === 0) break;
        const key = pick(keys);
        text += step(node, key);
        node = node[key];
      }
      return { node, text };
    };
    const numberRead = () => {
      if (numbers.length > 0 && rand() < 0.3) return pick(numbers);
      for (let tries = 0; tries < 6; tries++) {
        const { node, text } = somewhere();
        const keys = Object.keys(node).map((k) => (Array.isArray(node) ? Number(k) : k)).filter((k) => typeof node[k] === 'number');
        if (keys.length > 0) { const key = pick(keys); return { text: text + step(node, key), value: node[key] }; }
      }
      return null;
    };
    for (let s = 0; s < count; s++) {
      const roll = rand();
      if (roll < 0.12) {
        const { node, text } = somewhere(), name = `v${fresh++}`;
        statements.push(`let ${name} = ${text}`);
        refs.push({ name, node });
        continue;
      }
      if (roll < 0.2) {
        const source = numberRead();
        if (source === null) continue;
        const name = `n${fresh++}`;
        statements.push(`let ${name} = ${source.text}`);
        numbers.push({ text: name, value: source.value });
        continue;
      }
      const { node, text } = somewhere();
      const keys = Object.keys(node).map((k) => (Array.isArray(node) ? Number(k) : k)).filter((k) => !isNode(node[k]));
      let key;
      if (keys.length > 0 && rand() < 0.75) key = pick(keys);
      else if (Array.isArray(node)) key = node.length;
      else key = NAMES.find((k) => !(k in node)) ?? `k${fresh++}`;
      const target = text + step(node, key), current = node[key], kind = rand();
      let line, value;
      if (typeof current === 'number' && kind < 0.35) {
        const delta = 1 + int(9), op = rand() < 0.5 ? '+=' : '-=';
        line = `${target} ${op} ${delta}`;
        value = op === '+=' ? current + delta : current - delta;
      } else if (kind < 0.7) {
        const first = numberRead(), second = numberRead();
        if (first === null || second === null) continue;
        const op = rand() < 0.7 ? '+' : '-';
        line = `${target} = ${first.text} ${op} ${second.text}`;
        value = op === '+' ? first.value + second.value : first.value - second.value;
      } else {
        value = primitive();
        line = `${target} = ${typeof value === 'string' ? JSON.stringify(value) : String(value)}`;
      }
      if (line.length > 200) continue;
      statements.push(line);
      node[key] = value;
    }
    return statements;
  };
  // A large case keeps its answer near 120,000 characters: many calls on a small obj, or a few on a big one.
  const count = small ? 1 + int(3) : Math.min(40, Math.max(1, Math.floor(120000 / JSON.stringify(obj).length)));
  const mutators = Array.from({ length: count }, () => makeMutator(small ? int(5) : 2 + int(9)));
  return [obj, mutators];
}
